def orfs(s):
    stops={"TAA","TAG","TGA"}
    out=[]
    for fr in range(3):
        for st in range(fr,len(s)-2,3):
            if s[st:st+3]!="ATG": continue
            j=st
            while j+3<=len(s):
                if s[j:j+3] in stops:
                    if j+3-st>=100: out.append((st,j+3,j+3-st))
                    break
                j+=3
            else:
                if len(s)-st>=100: out.append((st,len(s),len(s)-st))
    return out
